    /**
     * @param  array<string,mixed>  $config
     * @param  array<string,string>  $credentials
     */
    private function messageGet(array $config, mixed $input, ?string $idempotencyKey, array $credentials, ?Transport $transport): ConnectorResult
    {
        unset($idempotencyKey);
        $result = ($this->client ?? new ConnectorClient)->call(
            Twilio::descriptor(),
            MessageGet::OPERATION,
            $config,
            [
                'method' => MessageGet::METHOD,
                'path' => MessageGet::path($config),
                'query' => MessageGet::body($config),
            ],
            $input,
            credentials: $credentials === [] ? null : $credentials,
            transport: $transport,
        );

        return $result;
    }

    /**
     * @param  array<string,mixed>  $config
     * @param  array<string,string>  $credentials
     */
    private function messageSend(array $config, mixed $input, ?string $idempotencyKey, array $credentials, ?Transport $transport): ConnectorResult
    {
        unset($idempotencyKey);
        $result = ($this->client ?? new ConnectorClient)->call(
            Twilio::descriptor(),
            MessageSend::OPERATION,
            $config,
            [
                'method' => MessageSend::METHOD,
                'path' => MessageSend::path($config),
                'form' => MessageSend::body($config),
            ],
            $input,
            credentials: $credentials === [] ? null : $credentials,
            transport: $transport,
        );

        return $result;
    }
